patch:
diff --git a/src/report.js b/src/report.js
index fa09ba9..ffb835c 100644
--- a/src/report.js
+++ b/src/report.js
@@ -219,6 +219,10 @@ export function summary(books, options = {}) {
     tags: byTag(books),
     decades: byDecade(books),
     top: topByValue(books, 3),
+    lowStock: [...books]
+      .filter((b) => b.stock > 0 && b.stock <= 3)
+      .map((b) => ({ id: b.id, title: b.title, stock: b.stock }))
+      .sort((a, b) => a.stock - b.stock || a.title.localeCompare(b.title)),
     outOfStock: outOfStock(books),
   }
 }
@@ -287,6 +291,11 @@ export function renderText(s) {
     parts.push('')
     parts.push(`Out of stock: ${s.outOfStock.map((b) => b.title).join(', ')}`)
   }
+  if (s.lowStock.length) {
+    parts.push('')
+    parts.push('Low stock')
+    for (const b of s.lowStock) parts.push(`${b.title} (${b.stock})`)
+  }
   return parts.join('\n') + '\n'
 }

@@ -353,6 +362,12 @@ export function renderMarkdown(s) {
     parts.push('')
     for (const b of s.outOfStock) parts.push(`- ${b.title}`)
   }
+  if (s.lowStock.length) {
+    parts.push('')
+    parts.push('## Low stock')
+    parts.push('')
+    for (const b of s.lowStock) parts.push(`- ${b.title} (${b.stock})`)
+  }
   return parts.join('\n') + '\n'
 }
